<script setup lang="ts">import {ref,onMounted,watch} from 'vue';import {useResearch} from '../stores/research';import {useCustomers} from '../stores/customers';import {useAuth} from '../stores/auth';import {importDataset} from '../api/datasets';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import EmptyState from '../components/common/EmptyState.vue';import {number} from '../utils/format';const store=useResearch(),customers=useCustomers(),auth=useAuth(),dataset=ref(0),search=ref(''),offset=ref(0),showImport=ref(false),name=ref(''),file=ref('members.csv'),csv=ref('code,recency,frequency,spend,learning_days\n'),{busy,error,perform}=useTask();async function load(){if(dataset.value)await customers.load(dataset.value,search.value,offset.value);}onMounted(()=>perform(async()=>{await store.load();dataset.value=store.datasets[0]?.id||0;await load();}));watch(dataset,()=>{offset.value=0;perform(load);});function searchRows(){offset.value=0;perform(load);}async function submit(){perform(async()=>{const result=await importDataset({name:name.value,source_file:file.value,csv_text:csv.value,description:'团队导入的匿名客户特征'});await store.load();dataset.value=result.id;showImport.value=false;});}</script><template><PageHeading eyebrow="SOURCE / ANONYMOUS FEATURES" title="客户数据，在同一口径下观察" description="只接收匿名编号与四个数值特征。先确认观察窗口，再开始研究。"><button v-if="auth.canEdit" class="outline" @click="showImport=!showImport">{{showImport?'收起导入':'导入特征 CSV +'}}</button></PageHeading><ErrorNotice :message="error" @retry="perform(load)"/><form v-if="showImport" class="import-form" @submit.prevent="submit"><h2>新建特征数据集</h2><div class="form-row"><label>数据集名称<input v-model="name" required minlength="2"></label><label>来源文件<input v-model="file" required></label></div><label>CSV 内容<textarea v-model="csv" rows="7" required></textarea></label><p class="muted">10–5000 行；code 唯一，数值不能为负或空。不会覆盖已有数据。</p><button class="primary" :disabled="busy">校验并导入 →</button></form><div class="data-toolbar"><label>观察数据集<select v-model="dataset"><option v-for="d in store.datasets" :key="d.id" :value="d.id">{{d.name}} · {{d.row_count}} 位</option></select></label><form @submit.prevent="searchRows"><input aria-label="搜索匿名编号" v-model="search" placeholder="搜索匿名编号，如 WA-002"><button class="outline">查找</button></form></div><div class="source-note"><b>↳ {{store.datasets.find(d=>d.id===dataset)?.source_file}}</b><span>{{store.datasets.find(d=>d.id===dataset)?.description}}</span></div><div class="table-wrap"><table><thead><tr><th>匿名编号</th><th>距上次学习 / 天</th><th>近90天购买 / 次</th><th>累计消费 / 元</th><th>近30天学习 / 天</th></tr></thead><tbody><tr v-for="c in customers.rows" :key="c.id"><td><strong>{{c.code}}</strong></td><td>{{number(c.recency,1)}}</td><td>{{number(c.frequency,1)}}</td><td>¥ {{number(c.spend,2)}}</td><td>{{number(c.learning_days,1)}}</td></tr></tbody></table></div><EmptyState v-if="!customers.rows.length" title="还没有匹配的数据" text="更换数据集或清空编号筛选；也可以导入带有表头的匿名特征 CSV。"/><div class="pagination"><span>共 {{customers.total}} 位 · 当前 {{offset+1}}—{{Math.min(offset+20,customers.total)}}</span><div><button :disabled="offset===0" @click="offset-=20;perform(load)">← 上一页</button><button :disabled="offset+20>=customers.total" @click="offset+=20;perform(load)">下一页 →</button></div></div></template>
